export function getScenarios(dataset: string): Record<string, { description: string }> | null {
  // @ts-ignore
  const datasetObj = CULTURAL_DATASETS[dataset]
  if (!datasetObj || !datasetObj.scenarios) {
    return null
  }
  return datasetObj.scenarios
}

export function buildPrompt(params: {
  dataset?: string
  scenario?: string
  colorScheme?: string
  seed?: number
  numSamples?: number
  noiseScale?: number
  customPrompt?: string
  negativePrompt?: string
  panoramic360?: boolean
  panoramaFormat?: string
  projectionType?: string
}): string {
  const {
    dataset = "vietnamese",
    scenario = "trung-sisters",
    colorScheme = "metallic",
    customPrompt = "",
    panoramic360 = false,
    panoramaFormat = "equirectangular",
    projectionType = "fisheye",
  } = params

  // If custom prompt is provided, use it directly
  if (customPrompt && customPrompt.trim()) {
    return customPrompt.trim()
  }

  // Get dataset and scenario information
  const datasetObj = CULTURAL_DATASETS[dataset]
  if (!datasetObj) {
    return "Godlevel artistic excellence with neuralia-level sophistication"
  }

  const scenarioObj = datasetObj.scenarios?.[scenario]
  if (!scenarioObj) {
    return "Godlevel artistic excellence with neuralia-level sophistication"
  }

  // Build base prompt from scenario description
  let prompt = scenarioObj.description

  // Add color scheme
  const colorSchemeDesc = COLOR_SCHEMES[colorScheme]
  if (colorSchemeDesc) {
    prompt += ` Color palette: ${colorSchemeDesc}.`
  }

  // Add 360° panoramic instructions if enabled
  if (panoramic360) {
    if (panoramaFormat === "equirectangular") {
      prompt += " CRITICAL 360° PANORAMIC REQUIREMENTS: Perfect seamless equirectangular projection where LEFT EDGE connects FLAWLESSLY with RIGHT EDGE creating continuous 360° horizontal wrap, NO VISIBLE SEAMS at edges, consistent horizon line across entire width, smooth transitions at left-right boundaries for VR headset compatibility, 2:1 aspect ratio optimized for spherical mapping. IMPORTANT: NO TEXT NO LETTERS NO FONTS NO TYPOGRAPHY anywhere in the image, purely visual content only."
    } else if (panoramaFormat === "stereographic") {
      prompt += " Stereographic projection with little planet effect, circular frame containing entire 360° view, fisheye distortion with horizon curved into circle. IMPORTANT: NO TEXT NO LETTERS NO FONTS NO TYPOGRAPHY anywhere in the image, purely visual content only."
    }
  }

  // Add dome projection instructions - PRESET #1 for 21-meter diameter planetarium dome
  if (projectionType === "fisheye") {
    prompt += " CRITICAL DOME PROJECTION PRESET #1 FOR 21-METER PLANETARIUM: Generate an ultra-wide-angle 180-degree hemispherical fisheye panorama designed for planetarium dome projection. Camera oriented straight up along z-axis (zenith view) resulting in extreme barrel distortion. Sky MUST be positioned at the absolute mathematically precise CENTER of the circular image, surrounded by curved environmental elements (natural or man-made structures). Establish perfect radial geometry extending from center outward to edges. Horizon is completely ABSENT, replaced by circular frame of immediate surroundings. All environmental elements curve dramatically inward toward frame edges creating immersive hemispherical perspective. This format is specifically designed to be projected onto a 21-meter diameter dome surface above viewers, NOT to create dome-shaped objects in the scene. IMPORTANT: NO TEXT NO LETTERS NO FONTS NO TYPOGRAPHY anywhere in the image, purely visual immersive content only."
  } else if (projectionType === "tunnel-up") {
    prompt += " Tunnel-up dome projection looking upward through cylindrical space for 21-meter planetarium dome, environmental elements surrounding viewer looking up. IMPORTANT: NO TEXT NO LETTERS NO FONTS NO TYPOGRAPHY anywhere in the image."
  } else if (projectionType === "tunnel-down") {
    prompt += " Tunnel-down dome projection looking downward through cylindrical space for 21-meter planetarium dome, bird's eye perspective with ground at center. IMPORTANT: NO TEXT NO LETTERS NO FONTS NO TYPOGRAPHY anywhere in the image."
  } else if (projectionType === "little-planet") {
    prompt += " Little planet dome projection with curved horizon and spherical world effect for 21-meter planetarium dome, planet-like curvature creating miniature world. IMPORTANT: NO TEXT NO LETTERS NO FONTS NO TYPOGRAPHY anywhere in the image."
  }

  return prompt
}
